1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<style>
5	    .gn-page { padding: 28px 20px; max-width: 1200px; margin: 0 auto; }
6	
7	    .gn-header {
8	        display: flex; align-items: center; justify-content: space-between;
9	        margin-bottom: 24px; flex-wrap: wrap; gap: 12px;
10	    }
11	    .gn-header-left { display: flex; align-items: center; gap: 14px; }
12	    .gn-logo {
13	        width: 42px; height: 42px; border-radius: 12px;
14	        background: linear-gradient(135deg, #a78bfa, #f472b6);
15	        display: flex; align-items: center; justify-content: center;
16	        font-size: 18px; font-weight: 900; color: #fff;
17	        box-shadow: 0 0 20px rgba(167,139,250,0.3);
18	    }
19	    .gn-header h1 {
20	        font-size: 1.5rem; font-weight: 700; text-align: left; letter-spacing: 0;
21	    }
22	    .gn-header-sub {
23	        font-size: 0.75rem; color: var(--text-dim); font-weight: 400;
24	    }
25	    .gn-tabs {
26	        display: flex; gap: 2px; background: rgba(255,255,255,0.03);
27	        border-radius: 10px; padding: 3px; border: 1px solid var(--border-light);
28	    }
29	    .gn-tab {
30	        padding: 8px 18px; border-radius: 8px; font-size: 0.78rem;
31	        font-weight: 600; color: var(--text-dim); cursor: pointer;
32	        transition: all 0.15s; border: none; background: none;
33	        font-family: var(--font-family);
34	    }
35	    .gn-tab:hover { color: var(--text-secondary); }
36	    .gn-tab.active {
37	        background: rgba(167,139,250,0.15); color: #a78bfa;
38	    }
39	
40	    .gn-section { display: none; }
41	    .gn-section.active { display: block; }
42	
43	    /* Filters */
44	    .gn-filters {
45	        display: flex; gap: 10px; margin-bottom: 20px; flex-wrap: wrap;
46	        align-items: center;
47	    }
48	    .gn-filter {
49	        padding: 6px 14px; border-radius: 20px; font-size: 0.72rem;
50	        font-weight: 600; cursor: pointer; border: 1px solid var(--border-strong);
51	        background: rgba(255,255,255,0.03); color: var(--text-muted);
52	        transition: all 0.15s; font-family: var(--font-family);
53	    }
54	    .gn-filter:hover { border-color: rgba(167,139,250,0.4); color: var(--text-secondary); }
55	    .gn-filter.active {
56	        background: rgba(167,139,250,0.12); border-color: rgba(167,139,250,0.4);
57	        color: #a78bfa;
58	    }
59	    .gn-filter-label {
60	        font-size: 0.68rem; color: var(--text-dim); text-transform: uppercase;
61	        letter-spacing: 0.06em; font-weight: 700; margin-right: 4px;
62	    }
63	    .gn-filter-sep {
64	        width: 1px; height: 20px; background: var(--border-medium);
65	    }
66	
67	    /* Event Cards */
68	    .gn-events { display: grid; grid-template-columns: 1fr; gap: 12px; }
69	
70	    .gn-event {
71	        background: var(--card-gradient); border: 1px solid var(--border-medium);
72	        border-radius: 12px; padding: 18px 20px;
73	        border-left: 3px solid var(--accent-slate);
74	        transition: transform 0.15s, border-color 0.15s;
75	        cursor: pointer;
76	    }
77	    .gn-event:hover {
78	        transform: translateY(-2px); border-color: rgba(167,139,250,0.3);
79	    }
80	    .gn-event.type-paid { border-left-color: var(--accent-green); }
81	    .gn-event.type-open-deck { border-left-color: var(--accent-amber); }
82	    .gn-event.type-guest-slot { border-left-color: var(--accent-blue); }
83	    .gn-event.type-collab { border-left-color: var(--accent-purple); }
84	    .gn-event.type-residency { border-left-color: var(--accent-gold); }
85	    .gn-event.matched {
86	        box-shadow: 0 0 0 1px rgba(167,139,250,0.2), 0 0 20px rgba(167,139,250,0.08);
87	    }
88	
89	    .gn-event-top {
90	        display: flex; align-items: flex-start; justify-content: space-between;
91	        gap: 12px; margin-bottom: 8px;
92	    }
93	    .gn-event-title {
94	        font-size: 0.95rem; font-weight: 700; color: #fff;
95	    }
96	    .gn-event-badges { display: flex; gap: 6px; flex-shrink: 0; }
97	
98	    .gn-event-meta {
99	        display: flex; gap: 16px; font-size: 0.75rem; color: var(--text-muted);
100	        margin-bottom: 8px; flex-wrap: wrap;
101	    }
102	    .gn-event-meta-item {
103	        display: flex; align-items: center; gap: 4px;
104	    }
105	    .gn-event-meta-item svg {
106	        width: 13px; height: 13px; stroke: currentColor; fill: none;
107	        stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round;
108	    }
109	
110	    .gn-event-desc {
111	        font-size: 0.78rem; color: var(--text-dim); line-height: 1.6;
112	        margin-bottom: 10px;
113	    }
114	
115	    .gn-event-genres {
116	        display: flex; gap: 5px; flex-wrap: wrap;
117	    }
118	    .gn-genre-tag {
119	        font-size: 0.62rem; font-weight: 700; padding: 2px 8px;
120	        border-radius: 10px; text-transform: uppercase; letter-spacing: 0.04em;
121	        background: rgba(255,255,255,0.05); color: var(--text-dim);
122	    }
123	    .gn-genre-tag.match {
124	        background: rgba(167,139,250,0.12); color: #a78bfa;
125	    }
126	
127	    .gn-match-badge {
128	        font-size: 0.58rem; font-weight: 700; padding: 2px 8px;
129	        border-radius: 10px; background: rgba(167,139,250,0.15);
130	        color: #a78bfa; text-transform: uppercase; letter-spacing: 0.04em;
131	    }
132	
133	    .gn-fee-badge {
134	        font-size: 0.62rem; font-weight: 700; padding: 2px 8px;
135	        border-radius: 10px; background: rgba(74,222,128,0.12);
136	        color: var(--accent-green);
137	    }
138	
139	    /* Set Tracker */
140	    .gn-sets { display: grid; grid-template-columns: 1fr; gap: 10px; }
141	
142	    .gn-set {
143	        background: var(--card-gradient); border: 1px solid var(--border-medium);
144	        border-radius: 12px; padding: 16px 20px;
145	        display: flex; align-items: center; gap: 16px;
146	    }
147	    .gn-set-icon {
148	        width: 40px; height: 40px; border-radius: 10px;
149	        display: flex; align-items: center; justify-content: center;
150	        font-size: 18px; flex-shrink: 0;
151	    }
152	    .gn-set-icon.posted {
153	        background: rgba(74,222,128,0.12); color: var(--accent-green);
154	    }
155	    .gn-set-icon.unposted {
156	        background: rgba(251,146,60,0.12); color: var(--accent-amber);
157	    }
158	    .gn-set-info { flex: 1; min-width: 0; }
159	    .gn-set-title {
160	        font-size: 0.88rem; font-weight: 600; color: #fff;
161	        white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
162	    }
163	    .gn-set-meta {
164	        font-size: 0.72rem; color: var(--text-dim);
165	        display: flex; gap: 12px; flex-wrap: wrap;
166	    }
167	    .gn-set-actions { display: flex; gap: 6px; flex-shrink: 0; }
168	
169	    .gn-nudge {
170	        background: rgba(251,146,60,0.08); border: 1px solid rgba(251,146,60,0.2);
171	        border-radius: 10px; padding: 12px 16px; margin-bottom: 16px;
172	        display: flex; align-items: center; gap: 10px;
173	        font-size: 0.78rem; color: var(--accent-amber);
174	    }
175	    .gn-nudge-icon { font-size: 18px; flex-shrink: 0; }
176	
177	    /* Log Set Modal */
178	    .gn-modal-overlay {
179	        position: fixed; inset: 0;
180	        background: rgba(5,10,16,0.75); backdrop-filter: blur(6px);
181	        z-index: 500; display: none; align-items: center; justify-content: center;
182	    }
183	    .gn-modal-overlay.open { display: flex; }
184	    .gn-modal {
185	        background: linear-gradient(135deg, #1a2738, #11202f);
186	        border: 1px solid rgba(255,255,255,0.10); border-radius: 14px;
187	        padding: 24px 26px; max-width: 520px; width: calc(100% - 40px);
188	        box-shadow: 0 24px 80px rgba(0,0,0,0.55);
189	        max-height: 90vh; overflow-y: auto;
190	    }
191	
192	    /* Empty state */
193	    .gn-empty {
194	        text-align: center; padding: 60px 20px; color: var(--text-dim);
195	    }
196	    .gn-empty h3 { color: var(--text-muted); margin-bottom: 8px; }
197	
198	    @media (max-width: 768px) {
199	        .gn-header { flex-direction: column; align-items: flex-start; }
200	        .gn-event-meta { flex-direction: column; gap: 4px; }
201	        .gn-set { flex-direction: column; align-items: flex-start; }
202	    }
203	</style>
204	</head>
205	<body>
206	<div class="gn-page">
207	    <div class="gn-header">
208	        <div class="gn-header-left">
209	            <div class="gn-logo">G</div>
210	            <div>
211	                <h1>GrooveNet</h1>
212	                <div class="gn-header-sub">Event Discovery + Set Tracker</div>
213	            </div>
214	        </div>
215	        <div class="gn-tabs">
216	            <button class="gn-tab active" data-tab="discover">Discover</button>
217	            <button class="gn-tab" data-tab="my-sets">My Sets</button>
218	            <button class="gn-tab" data-tab="matched">For You</button>
219	        </div>
220	    </div>
221	
222	    <!-- KPIs -->
223	    <div class="kpi-row" id="gn-kpis"></div>
224	
225	    <!-- Nudges for unposted sets -->
226	    <div id="gn-nudges"></div>
227	
228	    <!-- DISCOVER TAB -->
229	    <div class="gn-section active" id="tab-discover">
230	        <div class="gn-filters" id="gn-filters">
231	            <span class="gn-filter-label">Type</span>
232	            <button class="gn-filter active" data-filter-type="all">All</button>
233	            <button class="gn-filter" data-filter-type="open-deck">Open Deck</button>
234	            <button class="gn-filter" data-filter-type="paid">Paid</button>
235	            <button class="gn-filter" data-filter-type="guest-slot">Guest Slot</button>
236	            <button class="gn-filter" data-filter-type="collab">Collab</button>
237	            <button class="gn-filter" data-filter-type="residency">Residency</button>
238	            <div class="gn-filter-sep"></div>
239	            <span class="gn-filter-label">Location</span>
240	            <button class="gn-filter active" data-filter-loc="all">All</button>
241	        </div>
242	        <div class="gn-events" id="gn-events"></div>
243	    </div>
244	
245	    <!-- MY SETS TAB -->
246	    <div class="gn-section" id="tab-my-sets">
247	        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
248	            <h3>Set History</h3>
249	            <button class="btn btn-primary btn-sm" onclick="openLogSetModal()">+ Log Set</button>
250	        </div>
251	        <div class="gn-sets" id="gn-sets"></div>
252	    </div>
253	
254	    <!-- FOR YOU TAB -->
255	    <div class="gn-section" id="tab-matched">
256	        <div style="margin-bottom:16px;">
257	            <h3>Events Matched to Your Profile</h3>
258	            <p style="font-size:0.78rem;color:var(--text-dim);margin-top:4px;">
259	                Based on your genres, location, and availability.
260	            </p>
261	        </div>
262	        <div class="gn-events" id="gn-matched"></div>
263	    </div>
264	</div>
265	
266	<!-- Log Set Modal -->
267	<div class="gn-modal-overlay" id="log-set-modal">
268	    <div class="gn-modal">
269	        <h2>Log a Set</h2>
270	        <div class="form-group">
271	            <label class="form-label">Event / Night Name</label>
272	            <input class="form-input" id="set-event" placeholder="e.g. Underground Sessions">
273	        </div>
274	        <div class="form-grid">
275	            <div class="form-group">
276	                <label class="form-label">Venue</label>
277	                <input class="form-input" id="set-venue" placeholder="e.g. The Vault">
278	            </div>
279	            <div class="form-group">
280	                <label class="form-label">Date</label>
281	                <input class="form-input" id="set-date" type="date">
282	            </div>
283	        </div>
284	        <div class="form-grid">
285	            <div class="form-group">
286	                <label class="form-label">Set Type</label>
287	                <select class="form-select" id="set-type">
288	                    <option value="open-deck">Open Deck</option>
289	                    <option value="support">Support</option>
290	                    <option value="headliner">Headliner</option>
291	                    <option value="b2b">B2B</option>
292	                    <option value="guest">Guest Slot</option>
293	                    <option value="residency">Residency</option>
294	                </select>
295	            </div>
296	            <div class="form-group">
297	                <label class="form-label">Duration (min)</label>
298	                <input class="form-input" id="set-duration" type="number" placeholder="60">
299	            </div>
300	        </div>
301	        <div class="form-group">
302	            <label class="form-label">Recording Link</label>
303	            <input class="form-input" id="set-recording" placeholder="SoundCloud / Mixcloud / YouTube URL">
304	            <div class="form-hint">Leave blank if not recorded — we'll remind you to upload later.</div>
305	        </div>
306	        <div class="form-group">
307	            <label class="form-label">Notes</label>
308	            <textarea class="form-textarea" id="set-notes" placeholder="How did it go? What worked?"></textarea>
309	        </div>
310	        <div class="modal-actions">
311	            <button class="btn btn-back btn-sm" onclick="closeLogSetModal()">Cancel</button>
312	            <button class="btn btn-primary btn-sm" onclick="saveSet()">Save Set</button>
313	        </div>
314	    </div>
315	</div>
316	
317	<script>
318	(function() {
319	    var events = [];
320	    var sets = [];
321	    var profile = {};
322	    var activeTab = 'discover';
323	    var filterType = 'all';
324	    var filterLoc = 'all';
325	
326	    function loadData() {
327	        return Promise.all([
328	            fetch('/data/groovenet-events.json').then(function(r) { return r.ok ? r.json() : []; }).catch(function() { return []; }),
329	            fetch('/data/groovenet-sets.json').then(function(r) { return r.ok ? r.json() : []; }).catch(function() { return []; }),
330	            fetch('/data/groovenet-profile.json').then(function(r) { return r.ok ? r.json() : {}; }).catch(function() { return {}; })
331	        ]).then(function(res) {
332	            events = res[0];
333	            sets = res[1];
334	            profile = res[2];
335	            render();
336	        });
337	    }
338	
339	    function getLocations() {
340	        var locs = {};
341	        events.forEach(function(e) { locs[e.location] = true; });
342	        return Object.keys(locs).sort();
343	    }
344	
345	    function matchScore(evt) {
346	        if (!profile.genres || !profile.genres.length) return 0;
347	        var score = 0;
348	        var pg = profile.genres.map(function(g) { return g.toLowerCase(); });
349	        evt.genres.forEach(function(g) {
350	            if (pg.indexOf(g.toLowerCase()) !== -1) score += 2;
351	        });
352	        if (profile.location && evt.location.toLowerCase() === profile.location.toLowerCase()) score += 3;
353	        var day = new Date(evt.date).toLocaleDateString('en-US', { weekday: 'long' }).toLowerCase();
354	        if (profile.available_days && profile.available_days.indexOf(day) !== -1) score += 1;
355	        return score;
356	    }
357	
358	    function renderKPIs() {
359	        var upcoming = events.filter(function(e) { return new Date(e.date) >= new Date(); }).length;
360	        var totalSets = sets.length;
361	        var unposted = sets.filter(function(s) { return !s.posted; }).length;
362	        var openDecks = events.filter(function(e) { return e.type === 'open-deck' && new Date(e.date) >= new Date(); }).length;
363	
364	        document.getElementById('gn-kpis').innerHTML =
365	            '<div class="kpi"><div class="kpi-val text-purple">' + upcoming + '</div><div class="kpi-label">Upcoming Events</div></div>' +
366	            '<div class="kpi"><div class="kpi-val text-green">' + totalSets + '</div><div class="kpi-label">Sets Played</div></div>' +
367	            '<div class="kpi"><div class="kpi-val ' + (unposted > 0 ? 'text-amber' : 'text-green') + '">' + unposted + '</div><div class="kpi-label">Unposted Sets</div></div>' +
368	            '<div class="kpi"><div class="kpi-val text-amber">' + openDecks + '</div><div class="kpi-label">Open Decks</div></div>';
369	    }
370	
371	    function renderNudges() {
372	        var unposted = sets.filter(function(s) { return !s.posted; });
373	        var html = '';
374	        unposted.forEach(function(s) {
375	            html += '<div class="gn-nudge">' +
376	                '<span class="gn-nudge-icon">&#9888;</span>' +
377	                '<span>Your set from <strong>' + esc(s.event_title) + '</strong> (' + s.date + ') hasn\'t been posted yet. ' +
378	                '<a href="#" onclick="openEditSet(\'' + s.id + '\');return false;" style="color:var(--accent-blue);text-decoration:underline;">Add recording link</a></span>' +
379	                '</div>';
380	        });
381	        document.getElementById('gn-nudges').innerHTML = html;
382	    }
383	
384	    function renderLocFilters() {
385	        var locs = getLocations();
386	        var container = document.getElementById('gn-filters');
387	        var existingLocBtns = container.querySelectorAll('[data-filter-loc]');
388	        existingLocBtns.forEach(function(b) { if (b.dataset.filterLoc !== 'all') b.remove(); });
389	        locs.forEach(function(loc) {
390	            var btn = document.createElement('button');
391	            btn.className = 'gn-filter' + (filterLoc === loc ? ' active' : '');
392	            btn.dataset.filterLoc = loc;
393	            btn.textContent = loc;
394	            btn.addEventListener('click', function() {
395	                filterLoc = loc;
396	                updateFilterUI();
397	                renderEvents();
398	            });
399	            container.appendChild(btn);
400	        });
401	    }
402	
403	    function renderEvents() {
404	        var filtered = events.filter(function(e) {
405	            if (new Date(e.date) < new Date(new Date().toDateString())) return false;
406	            if (filterType !== 'all' && e.type !== filterType) return false;
407	            if (filterLoc !== 'all' && e.location !== filterLoc) return false;
408	            return true;
409	        });
410	
411	        filtered.sort(function(a, b) { return new Date(a.date) - new Date(b.date); });
412	
413	        if (filtered.length === 0) {
414	            document.getElementById('gn-events').innerHTML =
415	                '<div class="gn-empty"><h3>No events found</h3><p>Try adjusting your filters.</p></div>';
416	            return;
417	        }
418	
419	        var html = '';
420	        filtered.forEach(function(e) {
421	            var score = matchScore(e);
422	            var isMatch = score >= 3;
423	            var pg = (profile.genres || []).map(function(g) { return g.toLowerCase(); });
424	
425	            html += '<div class="gn-event type-' + e.type + (isMatch ? ' matched' : '') + '">';
426	            html += '<div class="gn-event-top">';
427	            html += '<div class="gn-event-title">' + esc(e.title) + '</div>';
428	            html += '<div class="gn-event-badges">';
429	            if (isMatch) html += '<span class="gn-match-badge">Match</span>';
430	            html += '<span class="badge ' + typeBadgeClass(e.type) + '">' + typeLabel(e.type) + '</span>';
431	            if (e.paid && e.fee_range) html += '<span class="gn-fee-badge">&#163;' + e.fee_range + '</span>';
432	            html += '</div></div>';
433	
434	            html += '<div class="gn-event-meta">';
435	            html += metaItem('M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z', e.venue + ', ' + e.location);
436	            html += metaItem('M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 012 2v14a2 2 0 01-2 2H5a2 2 0 01-2-2V6a2 2 0 012-2z', formatDate(e.date) + ' @ ' + e.time);
437	            html += metaItem('M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2', e.promoter);
438	            if (e.capacity) html += metaItem('M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2', e.capacity + ' capacity');
439	            html += '</div>';
440	
441	            html += '<div class="gn-event-desc">' + esc(e.description) + '</div>';
442	
443	            html += '<div class="gn-event-genres">';
444	            e.genres.forEach(function(g) {
445	                var isGenreMatch = pg.indexOf(g.toLowerCase()) !== -1;
446	                html += '<span class="gn-genre-tag' + (isGenreMatch ? ' match' : '') + '">' + g + '</span>';
447	            });
448	            html += '</div>';
449	            html += '</div>';
450	        });
451	
452	        document.getElementById('gn-events').innerHTML = html;
453	    }
454	
455	    function renderMatched() {
456	        var scored = events.filter(function(e) {
457	            return new Date(e.date) >= new Date(new Date().toDateString());
458	        }).map(function(e) {
459	            return { event: e, score: matchScore(e) };
460	        }).filter(function(s) {
461	            return s.score >= 2;
462	        });
463	        scored.sort(function(a, b) { return b.score - a.score; });
464	
465	        if (scored.length === 0) {
466	            document.getElementById('gn-matched').innerHTML =
467	                '<div class="gn-empty"><h3>No matches yet</h3><p>Update your profile genres and location to see matched events.</p></div>';
468	            return;
469	        }
470	
471	        var pg = (profile.genres || []).map(function(g) { return g.toLowerCase(); });
472	        var html = '';
473	        scored.forEach(function(s) {
474	            var e = s.event;
475	            html += '<div class="gn-event type-' + e.type + ' matched">';
476	            html += '<div class="gn-event-top">';
477	            html += '<div class="gn-event-title">' + esc(e.title) + '</div>';
478	            html += '<div class="gn-event-badges">';
479	            html += '<span class="gn-match-badge">Score: ' + s.score + '</span>';
480	            html += '<span class="badge ' + typeBadgeClass(e.type) + '">' + typeLabel(e.type) + '</span>';
481	            if (e.paid && e.fee_range) html += '<span class="gn-fee-badge">&#163;' + e.fee_range + '</span>';
